  const pickerFrame = page.frameLocator('#picker-frame');
  const closeAgent = async () => { await agentFrame.getByRole('button', { name: '대화 닫기', exact: true }).click(); await page.getByRole('dialog', { name: '에이전트 간 대화', exact: true }).waitFor({ state: 'hidden' }); };
