    assert.equal(await page.getByRole('button', { name: '예약 날짜 수정 대화', exact: true }).count(), 0);
    assert.equal(await conversation().getByRole('button', { name: /그룹 대화/ }).count(), 0);
    assert.equal(await conversation().getByRole('button', { name: /대화 보기$/ }).count(), 3);
    await input().fill('원래 Picky 초안');
