    await agentFrame.getByRole('heading', { name: 'Picky ↔ 루나', exact: true }).waitFor({ state: 'visible' });
    assert.equal(await agentFrame.getByRole('textbox').count(), 0);
    assert(await agentFrame.getByRole('article', { name: 'Picky 메시지', exact: true }).getByText('날짜를 바꾸면 인원이 초기화되는 원인을 조사해줘.', { exact: true }).isVisible());
    assert(await agentFrame.getByRole('article', { name: '루나 메시지', exact: true }).getByText('확인했어요. 맡은 일을 진행할게요.', { exact: true }).isVisible());
