    assert.equal(await page.getByText('5분 뒤 민트에게만 보낼 메시지', { exact: true }).count(), 1);
    await page.clock.fastForward(10000);
    assert.equal(await page.getByText('5분 뒤 민트에게만 보낼 메시지', { exact: true }).count(), 1);
